Key":"FOUND-TEST-PURPOSE-003","sectionKey":"purpose","sectionTitle":"Match method, purpose and example","questionType":"single","analyticsTitle":"Match method, purpose and example item 03","ordinal":16,"maxScore":1,"topicId":"09726e6e-8e0b-550b-8a96-bfccae797bdd","skillKey":null},{"id":"40097f6f-675c-5945-8118-650bf5bc2d9f","stableKey":"FOUND-TEST-CASE-001","sectionKey":"test-cases","sectionTitle":"Useful test cases","questionType":"multiple","analyticsTitle":"Useful test cases item 01","ordinal":17,"maxScore":1,"topicId":"b765a673-820f-5279-ab19-cddbde3c6086","skillKey":null},{"id":"82bb33dc-fc4d-50a4-8ed8-1fea63ec0587","stableKey":"FOUND-TEST-CASE-002","sectionKey":"test-cases","sectionTitle":"Useful test cases","questionType":"single","analyticsTitle":"Useful test cases item 02","ordinal":18,"maxScore":1,"topicId":"b765a673-820f-5279-ab19-cddbde3c6086","skillKey":null},{"id":"80e2a760-add0-52ca-b138-6ed3132ec9e1","stableKey":"FOUND-TEST-CASE-003","sectionKey":"test-cases","sectionTitle":"Useful test cases","questionType":"single","analyticsTitle":"Useful test cases item 03","ordinal":19,"maxScore":1,"topicId":"b765a673-820f-5279-ab19-cddbde3c6086","skillKey":null},{"id":"8d95b2f0-32f4-543f-8450-2ac30381787e","stableKey":"FOUND-TEST-ITER-001","sectionKey":"iteration","sectionTitle":"Testing and iteration","questionType":"order","analyticsTitle":"Testing and iteration item 01","ordinal":20,"maxScore":1,"topicId":"2945a786-4e8d-53fe-aff3-63792291edf3","skillKey":null},{"id":"afe1fd31-84f2-515d-ade2-5c35f60c6b88","stableKey":"FOUND-TEST-ITER-002","sectionKey":"iteration","sectionTitle":"Testing and iteration","questionType":"single","analyticsTitle":"Testing and iteration item 02","ordinal":21,"maxScore":1,"topicId":"2945a786-4e8d-53fe-aff3-63792291edf3","skillKey":null},{"id":"b5578d88-9aa8-5705-8823-e29efada26ca","stableKey":"FOUND-TEST-ITER-003","sectionKey":"iteration","sectionTitle":"Testing and iteration","questionType":"single","analyticsTitle":"Testing and iteration item 03","ordinal":22,"maxScore":1,"topicId":"2945a786-4e8d-53fe-aff3-63792291edf3","skillKey":null}]}}]}$manifest$::jsonb;
  activity_record jsonb;
  version_record jsonb;
  topic_record jsonb;
  skill_record jsonb;
  language_record jsonb;
  question_record jsonb;
  existing_version learning.activity_versions%rowtype;
begin
  insert into learning.courses (id, stable_key, code, title, qualification_level, active)
  values (
    (manifest #>> '{course,id}')::uuid,
    manifest #>> '{course,stableKey}',
    manifest #>> '{course,code}',
    manifest #>> '{course,title}',
    manifest #>> '{course,qualificationLevel}',
    (manifest #>> '{course,active}')::boolean
  )
  on conflict (id) do update set
    stable_key = excluded.stable_key,
    code = excluded.code,
    title = excluded.title,
    qualification_level = excluded.qualification_level,
    active = excluded.active,
    updated_at = now();

  insert into learning.modules (id, course_id, stable_key, title, sort_order, active)
  values (
    (manifest #>> '{module,id}')::uuid,
    (manifest #>> '{course,id}')::uuid,
    manifest #>> '{module,stableKey}',
    manifest #>> '{module,title}',
    (manifest #>> '{module,sortOrder}')::integer,
    (manifest #>> '{module,active}')::boolean
  )
  on conflict (id) do update set
    title = excluded.title,
    sort_order = excluded.sort_order,
    active = excluded.active,
    updated_at = now();

  for language_record in select value from jsonb_array_elements(manifest -> 'languages')
  loop
    insert into learning.coding_languages (id, stable_key, title, sort_order, active)
    values (
      (language_record ->> 'id')::uuid,
      language_record ->> 'stableKey',
      language_record ->> 'title',
      (language_record ->> 'sortOrder')::integer,
      (language_record ->> 'active')::boolean
    )
    on conflict (id) do update set
      title = excluded.title,
      sort_order = excluded.sort_order,
      active = excluded.active;
  end loop;

  for skill_record in select value from jsonb_array_elements(manifest -> 'skills')
  loop
    insert into learning.skills (id, module_id, stable_key, title, sort_order, active)
    values (
      (skill_record ->> 'id')::uuid,
      (manifest #>> '{module,id}')::uuid,
      skill_record ->> 'stableKey',
      skill_record ->> 'title',
      (skill_record ->> 'sortOrder')::integer,
      (skill_record ->> 'active')::boolean
    )
    on conflict (id) do update set
      title = excluded.title,
      sort_order = excluded.sort_order,
      active = excluded.active,
      updated_at = now();
  end loop;

  for topic_record in select value from jsonb_array_elements(manifest -> 'topics')
  loop
    insert into learning.topics (id, module_id, stable_key, title, sort_order, active)
    values (
      (topic_record ->> 'id')::uuid,
      (manifest #>> '{module,id}')::uuid,
      topic_record ->> 'stableKey',
      topic_record ->> 'title',
      (topic_record ->> 'sortOrder')::integer,
      (topic_record ->> 'active')::boolean
    )
    on conflict (id) do update set
      title = excluded.title,
      sort_order = excluded.sort_order,
      active = excluded.active,
      updated_at = now();
  end loop;

  for activity_record in select value from jsonb_array_elements(manifest -> 'activities')
  loop
    version_record := activity_record -> 'version';
    insert into learning.activities (id, module_id, stable_key, title, activity_type, git_path, active)
    values (
      (activity_record ->> 'id')::uuid,
      (manifest #>> '{module,id}')::uuid,
      activity_record ->> 'stableKey',
      activity_record ->> 'title',
      activity_record ->> 'activityType',
      activity_record ->> 'gitPath',
      (activity_record ->> 'active')::boolean
    )
    on conflict (id) do update set
      title = excluded.title,
      activity_type = excluded.activity_type,
      git_path = excluded.git_path,
      active = excluded.active,
      updated_at = now();

    select * into existing_version
    from learning.activity_versions
    where id = (version_record ->> 'id')::uuid;

    if found and (
      existing_version.activity_id <> (activity_record ->> 'id')::uuid
      or existing_version.version <> version_record ->> 'version'
      or existing_version.content_hash <> version_record ->> 'contentHash'
      or existing_version.max_score <> (version_record ->> 'maxScore')::numeric
      or existing_version.question_count <> (version_record ->> 'questionCount')::integer
    ) then
      raise exception using errcode = '23514', message = 'FOUNDATIONS_MANIFEST_VERSION_DRIFT';
    end if;

    insert into learning.activity_versions (
      id, activity_id, version, content_hash, git_commit_sha, max_score, question_count
    ) values (
      (version_record ->> 'id')::uuid,
      (activity_record ->> 'id')::uuid,
      version_record ->> 'version',
      version_record ->> 'contentHash',
      version_record ->> 'gitCommitSha',
      (version_record ->> 'maxScore')::numeric,
      (version_record ->> 'questionCount')::integer
    ) on conflict (id) do nothing;

    select * into strict existing_version
    from learning.activity_versions
    where id = (version_record ->> 'id')::uuid;

    if existing_version.published_at is null then
      for question_record in select value from jsonb_array_elements(version_record -> 'questions')
      loop
        insert into learning.questions (
          id, activity_version_id, stable_key, section_key, section_title,
          question_type, analytics_title, ordinal, max_score
        ) values (
          (question_record ->> 'id')::uuid,
          existing_version.id,
          question_record ->> 'stableKey',
          question_record ->> 'sectionKey',
          question_record ->> 'sectionTitle',
          question_record ->> 'questionType',
          question_record ->> 'analyticsTitle',
          (question_record ->> 'ordinal')::integer,
          (question_record ->> 'maxScore')::numeric
        ) on conflict (id) do nothing;

        insert into learning.question_topics (question_id, topic_id, weight)
        values (
          (question_record ->> 'id')::uuid,
          (question_record ->> 'topicId')::uuid,
          1
        ) on conflict (question_id, topic_id) do nothing;

        if question_record ->> 'skillKey' is not null then
          insert into learning.question_skills (question_id, skill_id, weight)
          select
            (question_record ->> 'id')::uuid,
            skill.id,
            1
          from learning.skills as skill
          where skill.module_id = (manifest #>> '{module,id}')::uuid
            and skill.stable_key = question_record ->> 'skillKey'
          on conflict (question_id, skill_id) do nothing;
        end if;
      end loop;

      for language_record in
        select value from jsonb_array_elements(version_record -> 'supportedProgrammingLanguages')
      loop
        insert into learning.activity_version_languages (activity_version_id, coding_language_id)
        select existing_version.id, language.id
        from learning.coding_languages as language
        where language.stable_key = language_record #>> '{}'
        on conflict (activity_version_id, coding_language_id) do nothing;
      end loop;

      if (select count(*) from learning.questions where activity_version_id = existing_version.id)
          <> existing_version.question_count
         or (select coalesce(sum(max_score), 0) from learning.questions where activity_version_id = existing_version.id)
          <> existing_version.max_score then
        raise exception using errcode = '23514', message = 'FOUNDATIONS_MANIFEST_QUESTION_TOTAL_MISMATCH';
      end if;

      update learning.activity_versions
      set published_at = (version_record ->> 'publishedAt')::timestamptz
      where id = existing_version.id;
    end if;
  end loop;
end
$migration$;
